def _value(raw):
    """Parse a raw (unquoted-key) value, handling surrounding quotes."""
    value = raw.strip()
    if not value.startswith(QUOTE):
        if QUOTE in value:
            raise ValueError(f"stray quote in value: {raw!r}")
        return value
    out = []
    i = 1
    end = len(value)
