        ch = value[i]
        if ch == QUOTE:
            if i + 1 < end and value[i + 1] == QUOTE:
                out.append(QUOTE)
                i += 2
                continue
            if i != end - 1:
                raise ValueError(f"bad quoted value: {raw!r}")
            return "".join(out)
        out.append(ch)
        i += 1
    raise ValueError(f"unclosed quote in value: {raw!r}")


